<template><div class="page"><el-card><template #header><span>库存预警</span></template><el-table :data="list" border><el-table-column prop="id" label="ID" width="70"/><el-table-column label="商品" min-width="200"><template #default="{row}"><div style="display:flex;align-items:center;gap:10px"><el-image v-if="row.main_image" :src="row.main_image" style="width:50px;height:50px" fit="cover"/><span>{{row.name}}</span></div></template></el-table-column><el-table-column prop="stock" label="当前库存" width="100"/><el-table-column prop="warning_stock" label="预警值" width="100"/><el-table-column label="操作" width="150"><template #default="{row}"><el-button size="small" @click="setWarning(row)">设置预警</el-button></template></el-table-column></el-table></el-card></div></template><script setup>import{ref,onMounted}from'vue';import{ElMessage,ElMessageBox}from'element-plus';import request from'@/utils/request';const list=ref([]);const loadList=async()=>{const res=await request({url:'/stock-warnings'});list.value=res.data?.list||[]};const setWarning=async(row)=>{const{value}=await ElMessageBox.prompt('请输入预警库存值','设置预警',{inputValue:row.warning_stock||10,inputPattern:/^\d+$/,inputErrorMessage:'请输入数字'});await request({url:'/stock-warnings/setting',method:'post',data:{goods_id:row.id,warning_stock:parseInt(value)}});ElMessage.success('设置成功');loadList()};onMounted(()=>loadList())</script>
